```plantuml
@startuml
title Блок 15.1 - Разморозка договора

start

:Вход в интент\n"Разморозка договора";

:Использовать договор,\nопределенный входным сценарием;

if (Договор находится в заморозке?) then (Да)

  :Сообщить условия разморозки;

  :Запросить подтверждение;

  if (Подтверждение получено?) then (Да)

    :Повторно проверить состояние договора;

    if (Договор все еще в заморозке?) then (Да)

      :Выполнить разморозку;

      if (Операция успешна?) then (Да)
        :Сообщить об успешной разморозке;
        :Спросить, нужна ли еще помощь;

        if (Есть другой вопрос?) then (Да)
          :Перейти в другой интент;
          stop
        else (Нет)
          :Завершить разговор;
          stop
        endif

      else (Нет)
        :Сообщить об ошибке;
        :Предложить соединение со специалистом;
        stop
      endif

    else (Нет)
      :Сообщить, что заморозка уже снята;
      :Спросить, нужна ли еще помощь;
      stop
    endif

  else (Нет)

    if (Абонент отказался?) then (Да)
      :Сообщить, что заморозка останется активной;
      :Спросить, нужна ли еще помощь;
      stop
    else (Не распознано)
      :Повторить запрос подтверждения;

      if (Две неудачные попытки?) then (Да)
        :Предложить перевод на оператора;
        stop
      else (Нет)
        :Вернуться к запросу подтверждения;
        stop
      endif
    endif

  endif

else (Нет)

  :Сообщить, что договор не находится в заморозке;
  :Спросить, нужна ли помощь или оператор;

  if (Абонент просит оператора?) then (Да)
    :Соединить со специалистом;
    stop
  else (Нет)
    if (Есть другой вопрос?) then (Да)
      :Перейти в другой интент;
      stop
    else (Нет)
      :Завершить разговор;
      stop
    endif
  endif

endif

@enduml
```
